import{_ as t,C as r,o,c,j as a,a as d,G as i,a2 as l}from"./chunks/framework.BgSoyxN5.js";const k=JSON.parse('{"title":"Business Quality and TTM Stock Screener | TickerForge","description":"Find companies where TTM business score, Piotroski quality, or financial risk is improving or deteriorating versus the latest fiscal year.","frontmatter":{"title":"Business Quality and TTM Stock Screener | TickerForge","description":"Find companies where TTM business score, Piotroski quality, or financial risk is improving or deteriorating versus the latest fiscal year.","aside":false,"outline":false,"pageClass":"company-decision-radar-page"},"headers":[],"relativePath":"company-decision-radar.md","filePath":"company-decision-radar.md","lastUpdated":1784785156000}'),p={name:"company-decision-radar.md"};function h(m,e,u,g,f,y){const s=r("TickerForgeComplianceDisclaimer"),n=r("TickerForgeCompanyDecisionRadarWidget");return o(),c("div",null,[e[0]||(e[0]=a("h1",{id:"business-decision-radar",tabindex:"-1"},[d("Business Decision Radar "),a("a",{class:"header-anchor",href:"#business-decision-radar","aria-label":'Permalink to "Business Decision Radar"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Annual financial statements are useful, but they can hide changes already visible in the latest four reported quarters. The Business Decision Radar compares each company's latest TTM readings with its latest fiscal-year snapshot.",-1)),i(s),e[2]||(e[2]=a("p",null,"Use it to find improving businesses, quality companies waiting for a better entry, and companies whose annual picture still looks acceptable while recent fundamentals are weakening.",-1)),i(n,{"api-base":"https://api.ticker-forge.com"}),e[3]||(e[3]=l('<h2 id="free-screeners-vs-pro-decision-radar" tabindex="-1">Free Screeners vs Pro Decision Radar <a class="header-anchor" href="#free-screeners-vs-pro-decision-radar" aria-label="Permalink to &quot;Free Screeners vs Pro Decision Radar&quot;">​</a></h2><p>Free Stock Discovery is available as a live broad screener for business value, guarded fair value, cash flow, technical entry, and Workspace-unlocked Timing. Standard and Pro add stronger growth, quality, insider, Top Funds, and export layers.</p><p>Standard expands access to higher-score companies. Pro access unlocks the full Decision Radar evidence layer: TTM vs FY score history, quarter-by-quarter context, Piotroski changes, risk components, complete histories, and Excel research exports.</p><p><a href="/pricing">Compare Plans</a></p><h2 id="why-this-is-separate-from-smart-money-radar" tabindex="-1">Why This Is Separate From Smart Money Radar <a class="header-anchor" href="#why-this-is-separate-from-smart-money-radar" aria-label="Permalink to &quot;Why This Is Separate From Smart Money Radar&quot;">​</a></h2><p>The <a href="/smart-money-radar">Smart Money &amp; Insider Radar</a> asks where institutional and insider capital appears to be moving. This radar asks whether the underlying business itself is improving or deteriorating.</p><p>Those signals can reinforce each other, but they should not be merged into one ranking. A business can improve before funds notice it, while institutional buying can also appear before the reported fundamentals strengthen.</p><h2 id="understanding-the-screens" tabindex="-1">Understanding The Screens <a class="header-anchor" href="#understanding-the-screens" aria-label="Permalink to &quot;Understanding The Screens&quot;">​</a></h2><p><strong>Business Momentum</strong> requires a higher TTM business score while Piotroski, quality, and risk are not worsening. <strong>TTM Score Up</strong>, <strong>Quality Up</strong>, and <strong>Risk Down</strong> isolate individual improvements.</p><p><strong>Hidden Improvement</strong> looks for better fundamentals before technical timing fully confirms. <strong>Quality Pullback</strong> finds improving good businesses where the current action still favors patience. <strong>Deterioration Watch</strong> reverses the lens: the yearly view remains decent, but recent TTM evidence is weakening.</p><p>For risk-focused screening, start with <strong>Risk Down</strong> to find improving financial risk profiles and <strong>Deterioration Watch</strong> to catch stocks where recent TTM evidence is moving the wrong way before the annual snapshot fully reflects it.</p><h2 id="important-limitations" tabindex="-1">Important Limitations <a class="header-anchor" href="#important-limitations" aria-label="Permalink to &quot;Important Limitations&quot;">​</a></h2><p>TTM values aggregate the latest four available quarterly reports. They are not management guidance and may contain seasonality, acquisitions, reporting reclassifications, or incomplete provider data. A positive delta is a research lead, not an automatic buy signal.</p><p>Open any ticker in the <a href="/stock-widget">Stock Analysis Widget</a> to review the company in context. Use <a href="/portfolio-diagnostics">Portfolio Diagnostics</a> before turning a candidate into a position.</p>',14))])}const b=t(p,[["render",h]]);export{k as __pageData,b as default};
